import java.util.*;
import java.io.*;

public class Main {
    static final int MAX_DEPTH = 7;
    static final int LIMIT = 1000000;
    static final long MOD_A = 998244353;
    static final long MOD_B = 1000000007;
    static long total_input;
    static long count_total;
    static ArrayList<Integer>[] digits = new ArrayList[MAX_DEPTH];
    static int final_answer;
    static long[] prefix_sum_arr = new long[MAX_DEPTH];

    public static void main(String[] args) {
        for (int i = 0; i < MAX_DEPTH; i++) {
            digits[i] = new ArrayList<>();
        }
        Scanner sc = new Scanner(System.in);
        total_input = sc.nextLong();

        generate(0, 0);
        for (int d = 0; d <= 6; d++) {
            Collections.sort(digits[d]);
            long sum = 0;
            for (int v : digits[d]) {
                sum = (sum + v) % MOD_B;
            }
            prefix_sum_arr[d] = sum;
        }

        final_answer = 0;
        count_total = 0;
        process_node(0, 0L);
        System.out.println(final_answer);
        sc.close();
    }

    static void generate(int depth, long val) {
        count_total++;
        digits[depth].add((int)((count_total - val + MOD_A) % MOD_A));
        if (depth == 6) return;
        for (int digit = 0; digit < 10; digit++) {
            generate(depth + 1, val * 10 + digit);
        }
    }

    static void process_node(int depth, long v) {
        if (v > total_input) return;
        if (depth != 0) {
            if (v * LIMIT > total_input / 10 && (v + 1) * LIMIT - 1 <= total_input) {
                for (int i = 0, pwr = 1; i <= 6; i++, pwr *= 10) {
                    long coef = (count_total - (v * pwr) % MOD_A + MOD_A) % MOD_A;
                    ArrayList<Integer> arr = digits[i];
                    int idx = lowerBound(arr, (int)(MOD_A - coef));
                    long size = arr.size();
                    long sum = prefix_sum_arr[i];

                    final_answer = (int) ((final_answer + coef * size + sum) % MOD_B);
                    long count_greater = size - idx;
                    final_answer = (int) ((final_answer - (MOD_A * count_greater) % MOD_B + MOD_B) % MOD_B);
                }

                // Update total count
                for (int i = 0; i <= 6; i++) {
                    count_total += digits[i].size();
                }

                return;
            }
            final_answer = (int) ((final_answer + (++count_total - v % MOD_A + MOD_A) % MOD_A) % MOD_B);
        }

        int start_c = (depth == 0) ? 1 : 0;
        for (int c = start_c; c < 10; c++) {
            process_node(depth + 1, v * 10 + c);
        }
    }

    static int lowerBound(List<Integer> list, int key) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) < key)
                low = mid + 1;
            else
                high = mid;
        }
        return low;
    }
}
